package br.com.admeclesial.application.sacramento;
import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial;
import br.com.admeclesial.domain.sacramento.*; import br.com.admeclesial.infrastructure.persistence.sacramento.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class RegistroSacramentalApplicationServiceTest { @Mock RegistroSacramentalRepository repository; @Mock SacramentoRepository sacramentoRepository; RegistroSacramentalApplicationService service; Sacramento s; UUID su;
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);service=new RegistroSacramentalApplicationService(repository,sacramentoRepository);s=new Sacramento();var organizacao=new OrganizacaoEclesial();s.setOrganizacaoEclesial(organizacao);su=UUID.randomUUID();try{java.lang.reflect.Field fo=OrganizacaoEclesial.class.getDeclaredField("uuid");fo.setAccessible(true);fo.set(organizacao,UUID.randomUUID());java.lang.reflect.Field f=Sacramento.class.getDeclaredField("id");f.setAccessible(true);f.set(s,1L);}catch(Exception e){throw new RuntimeException(e);}when(sacramentoRepository.findByUuid(su)).thenReturn(Optional.of(s));when(repository.findBySacramentoId(anyLong())).thenReturn(Optional.empty());when(repository.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void deveCriarRegistro(){var r=service.salvar(new RegistroSacramentalRequest(su," 1 "," 2 "," 3 "," 4 "," obs "));assertEquals("1",r.livro());assertEquals("4",r.numeroRegistro());verify(repository).save(any());}
 @Test void deveAtualizarRegistroExistente(){var e=new RegistroSacramental();when(repository.findBySacramentoId(anyLong())).thenReturn(Optional.of(e));var r=service.salvar(new RegistroSacramentalRequest(su,"1",null,null,null,null));assertEquals("1",r.livro());verify(repository).save(e);}
 @Test void naoDeveRegistrarCancelado(){s.setStatus(StatusSacramento.CANCELADO);var ex=assertThrows(SacramentoBusinessException.class,()->service.salvar(new RegistroSacramentalRequest(su,"1",null,null,null,null)));assertTrue(ex.getMessage().contains("cancelado"));}
}
